import React from 'react';
import './App.css'; // Ton CSS global habituel

// --- ETAPE 1 : Importer le composant ---
// Si tes fichiers sont dans le même dossier que App.js :
import Timeline from './Timeline';

// OU SI tu les as mis dans un dossier "components" :
// import Timeline from './components/Timeline';

function App() {
  return (
    <div className="App">
      <header className="App-header">
        <h1>Mon Projet React</h1>
      </header>

      {/* --- ETAPE 2 : Utiliser le composant --- */}
      <main>
        <p>Voici la feuille de route du projet :</p>

        {/* C'est cette balise qui fait apparaître ta timeline */}
        <Timeline />

      </main>
    </div>
  );
}

export default App;
